/* JAH interactive demo — JAH-VIR-000001 · Variola virus
 * RUN ON PC: save as demo.js, then run:  node demo.js */
(function(){
var V={"name": "Variola virus", "species": "Variola virus", "family": "Poxviridae", "genus": "Orthopoxvirus", "baltimore": "Class I: dsDNA", "genome": "Double-stranded DNA, linear, about 186,000 base pairs", "structure": "Large brick-shaped enveloped virion, roughly 300 x 240 x 100 nm; complex internal structure with lateral bodies; replica", "transmission": "Respiratory droplets and prolonged close face-to-face contact; also via contaminated bedding and clothing", "hosts": "Humans only — no animal reservoir, which made eradication possible"};
console.log('VIRUS CARD — ' + V.name);
console.log('Species: ' + V.species + ' | Family: ' + V.family + ' (' + V.genus + ')');
console.log('Baltimore class: ' + V.baltimore);
console.log('Genome: ' + V.genome);
var kb=186;
console.log('Genome size bar (1 # ~= 8 kb): ' + "#######################" + ' ' + kb + ' kb');
var refs=[['Hepatitis D (smallest)',2],['This virus',kb],['Herpesvirus (large)',152],['Mimivirus (giant)',1180]];
console.log('--- genome size vs references (kb) ---');
refs.forEach(function(r){ console.log(r[0] + ': ' + r[1] + ' kb' + (r[0]==='This virus' ? '  <--' : '')); });
console.log('Transmission: ' + V.transmission);
console.log('Hosts: ' + V.hosts);
console.log('Structure: ' + V.structure + '...');
})();

